        }
    }
    return cnt;
}

class Solution {
    public long solve(int n) {
        long cnt = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = i; j <= n; j += i) {
                cnt++;
            }
        }
        return cnt;
    }
}
